```python
import PyPDF2
import docx
import logging

# Configure logging
logging.basicConfig(filename='document_handler.log', level=logging.ERROR,
                    format='%(asctime)s - %(levelname)s - %(message)s')

def handle_pdf(document_path):
    try:
        with open(document_path, 'rb') as file:
            reader = PyPDF2.PdfReader(file)
            text = ""
            for page in reader.pages:
                text += page.extract_text()
            return text
    except Exception as e:
        logging.error(f"Error handling PDF: {e} - Document: {document_path}")
        return None

def handle_docx(document_path):
    try:
        doc = docx.Document(document_path)
        text = "\n".join([para.text for para in doc.paragraphs])
        return text
    except Exception as e:
        logging.error(f"Error handling DOCX: {e} - Document: {document_path}")
        return None

def handle_other_format(document_path):
