        # Placeholder for handling other formats
        # You can add specific logic here for other formats
        return f"Content of {document_path}"
    except Exception as e:
        logging.error(f"Error handling other format: {e} - Document: {document_path}")
        return None

def handle_document(document_path):
    if document_path.endswith(".pdf"):
        return handle_pdf(document_path)
    elif document_path.endswith(".docx"):
        return handle_docx(document_path)
    else:
        return handle_other_format(document_path)

# Example usage
documents = [
    "example.pdf",
    "example.docx",
    "example.txt",  # Other format
]

for document in documents:
    content = handle_document(document)
    if content:
        print(f"Content of {document}: {content[:100]}...")
    else:
        print(f"Failed to handle {document}")
```

