```java
import org.apache.nifi.annotation.behavior.InputRequirement;
import org.apache.nifi.annotation.behavior.InputRequirement.Requirement;
import org.apache.nifi.annotation.lifecycle.OnScheduled;
import org.apache.nifi.components.PropertyDescriptor;
import org.apache.nifi.flowfile.FlowFile;
import org.apache.nifi.processor.AbstractProcessor;
import org.apache.nifi.processor.ProcessContext;
import org.apache.nifi.processor.ProcessSession;
import org.apache.nifi.processor.Relationship;
import org.apache.nifi.processor.util.StandardValidators;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

@InputRequirement(Requirement.INPUT_REQUIRED)
public class DocumentFormatValidator extends AbstractProcessor {

    public static final Relationship REL_SUCCESS = new Relationship.Builder()
            .name("success")
            .description("FlowFiles that pass validation")
            .build();

    public static final Relationship REL_FAILURE = new Relationship.Builder()
            .name("failure")
            .description("FlowFiles that fail validation")
            .build();

    private Set<String> allowedFormats;

    @Override
    protected void init(final PropertyDescriptor[] descriptors) {
        super.init(descriptors);
    }

    @Override
    public Set<Relationship> getRelationships() {
        return Collections.unmodifiableSet(new HashSet<>(Collections.singletonList(REL_SUCCESS)));
    }

    @Override
    public void onTrigger(final ProcessContext context, final ProcessSession session) {
        FlowFile file = session.get();
        if (file == null) {
            return;
        }

        String format = file.getAttribute("format");
        if (allowedFormats.contains(format)) {
            session.transfer(file, REL_SUCCESS);
        } else {
            session.transfer(file, REL_FAILURE);
        }
    }

    @OnScheduled
    public void onScheduled(final ProcessContext context) {
        allowedFormats = new HashSet<>();
        allowedFormats.add("format1");
        allowedFormats.add("format2");
        allowedFormats.add("format3");
    }
}
```

