```java
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.text.PDFTextStripper;

import java.io.File;
import java.io.IOException;
import java.io.StringWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class PdfExtractor {

    public static String extractTextFromPdf(File file) throws IOException {
        try (PDDocument document = PDDocument.load(file)) {
            PDFTextStripper stripper = new PDFTextStripper();
            stripper.setSortByPosition(true); // Optional: Sort text by position
            stripper.setStartPage(1); // Optional: Start page
            stripper.setEndPage(document.getNumberOfPages()); // Optional: End page
            StringWriter writer = new StringWriter();
            stripper.writeText(document, writer);
            return writer.toString();
        }
    }

    public static void main(String[] args) throws IOException {
