        // Single-threaded extraction
        long startTime = System.currentTimeMillis();
        String text = extractTextFromPdf(pdfFile);
        long endTime = System.currentTimeMillis();
        System.out.println("Extraction took " + (endTime - startTime) + " ms");

        // Multithreaded extraction (for multiple files)
        ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        File[] files = new File("path/to/your/pdf/directory").listFiles((dir, name) -> name.endsWith(".pdf"));

        if (files != null) {
            for (File file : files) {
                executorService.submit(() -> {
                    try {
                        String text = extractTextFromPdf(file);
                        // Process the extracted text
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                });
            }
        }

        executorService.shutdown();
    }
}
```

