        TaskEstimator estimator = new TaskEstimator();
        estimator.addTask(new Task("Design", 5));
        estimator.addTask(new Task("Implementation", 10));
        estimator.addTask(new Task("Testing", 5));
        estimator.addTask(new Task("Documentation", 5));

