import org.apache.nifi.annotation.behavior.EventDriven;
import org.apache.nifi.annotation.documentation.CapabilityDescription;
import org.apache.nifi.annotation.documentation.Tags;
import org.apache.nifi.components.PropertyDescriptor;
import org.apache.nifi.flowfile.FlowFile;
import org.apache.nifi.processor.AbstractProcessor;
import org.apache.nifi.processor.ProcessContext;
import org.apache.nifi.processor.ProcessSession;
import org.apache.nifi.processor.Relationship;
import org.apache.nifi.processor.util.StandardValidators;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;

@EventDriven
@Tags({"batch", "ingestion"})
@CapabilityDescription("Handles batch ingestion of documents with dynamic batch size based on file size.")
public class DynamicBatchIngestionProcessor extends AbstractProcessor {

    public static final Relationship REL_SUCCESS = new Relationship.Builder()
            .name("success")
            .description("Success relationship")
            .build();

    public static final Relationship REL_FAILURE = new Relationship.Builder()
            .name("failure")
            .description("Failure relationship")
            .build();

    private List<PropertyDescriptor> properties;
    private Set<Relationship> relationships;

    @Override
    protected void init(final Properties props) {
        final List<PropertyDescriptor> properties = Collections.emptyList();
        final Set<Relationship> relationships = Collections.emptySet();
        this.properties = properties;
        this.relationships = relationships;
    }

    @Override
    public Set<Relationship> getRelationships() {
        return relationships;
    }

    @Override
    public final List<PropertyDescriptor> getSupportedPropertyDescriptors() {
        return properties;
    }

    @Override
    public void onTrigger(final ProcessContext context, final ProcessSession session) {
        List<FlowFile> flowFiles = new ArrayList<>();
        long batchSizeBytes = 10 * 1024 * 1024; // 10MB batch size

        long currentBatchSize = 0;

        // Retrieve flow files in batches based on size
        while (session.get() != null && currentBatchSize < batchSizeBytes) {
            FlowFile flowFile = session.get();
            if (flowFile == null) {
                break;
            }
            long fileSize = flowFile.getSize();
            if (currentBatchSize + fileSize > batchSizeBytes) {
                break;
            }
            flowFiles.add(flowFile);
            currentBatchSize += fileSize;
        }

        if (!flowFiles.isEmpty()) {
            try {
                // Process the batch of documents
                processBatch(flowFiles, session);

                // Transfer the flow files to success relationship
                for (FlowFile flowFile : flowFiles) {
                    session.transfer(flowFile, REL_SUCCESS);
                }
            } catch (Exception e) {
                // Transfer the flow files to failure relationship
                for (FlowFile flowFile : flowFiles) {
                    session.transfer(flowFile, REL_FAILURE);
                }
                getLogger().error("Error processing batch of documents: {}", e);
            }
        }
    }

    private void processBatch(List<FlowFile> flowFiles, ProcessSession session) {
        // Your batch processing logic here
        for (FlowFile flowFile : flowFiles) {
            // Example: Update attributes or perform other operations
            session.putAttribute(flowFile, "processed", "true");
        }
    }
}
