public class AsyncDocumentHandler {
    public CompletableFuture<Void> handleDocumentAsync(Document document) {
        return CompletableFuture.runAsync(() -> {
            // Asynchronous document handling logic
            System.out.println("Handling document asynchronously: " + document.getId());
        });
    }
}
