private void logErrorToDatabase(Document document, Exception e) {
    String sql = "INSERT INTO errors (document_id, error_message, timestamp) VALUES (?, ?, ?)";
    try (Connection conn = dataSource.getConnection();
         PreparedStatement stmt = conn.prepareStatement(sql)) {
