### Step 5: Sending Notifications

You can also set up notifications for critical errors using email, SMS, or other notification services.

#### Example: Sending Email Notification

```java
import javax.mail.Message;
import javax.mail.MessagingException;
import javax.mail.Session;
import javax.mail.Transport;
import javax.mail.internet.InternetAddress;
import javax.mail.internet.MimeMessage;

private void sendNotificationEmail(Document document, Exception e) {
    Properties props = new Properties();
    props.put("mail.smtp.auth", "true");
    props.put("mail.smtp.starttls.enable", "true");
    props.put("mail.smtp.host", "smtp.gmail.com");
    props.put("mail.smtp.port", "587");

    Session session = Session.getInstance(props,
            new javax.mail.Authenticator() {
                protected PasswordAuthentication getPasswordAuthentication() {
                    return new PasswordAuthentication("username@gmail.com", "password");
                }
            });

    try {
        Message message = new MimeMessage(session);
        message.setFrom(new InternetAddress("username@gmail.com"));
        message.setRecipients(Message.RecipientType.TO,
                InternetAddress.parse("recipient@example.com"));
        message.setSubject("Parsing Error Notification");
        message.setText("Document ID: " + document.getId() + "\nError Message: " + e.getMessage());

        Transport.send(message);
    } catch (MessagingException mex) {
        getLogger().error("Error sending email notification: {}", mex);
    }
}
```

