     *
     * @param username The username of the user.
     * @param password The password of the user.
     * @param role The role to check for the user.
     * @return true if the user is authenticated and has the required role, false otherwise.
     */
    public boolean checkUserAccess(String username, String password, String role) {
        if (!authenticateUser(username, password)) {
            return false;
        }
        return authorizeUser(username, role);
    }
}
