import java.text.SimpleDateFormat;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.stream.Collectors;

public class MetadataTransformer {

    private SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");

    public Metadata transform(Metadata metadata) {
        metadata = normalizeDates(metadata);
        metadata = standardizeAuthors(metadata);
        metadata = cleanKeywords(metadata);
        metadata = validateCategories(metadata);
        return metadata;
    }

    private Metadata normalizeDates(Metadata metadata) {
        try {
            metadata.setCreationDate(dateFormat.format(dateFormat.parse(metadata.getCreationDate())));
        } catch (Exception e) {
            // Handle parsing exception
        }
        return metadata;
    }

    private Metadata standardizeAuthors(Metadata metadata) {
        metadata.setAuthor(metadata.getAuthor().trim().replaceAll("\\s+", " ").toUpperCase());
        return metadata;
    }

    private Metadata cleanKeywords(Metadata metadata) {
        Set<String> keywordsSet = new HashSet<>(Arrays.asList(metadata.getKeywords().split(",")));
        metadata.setKeywords(String.join(",", keywordsSet.stream().sorted().collect(Collectors.toList())));
        return metadata;
    }

