import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.ConcurrentHashMap;

public class JsonParser {

    private static final Logger logger = LoggerFactory.getLogger(JsonParser.class);
    private static final int THREAD_POOL_SIZE = 4; // Adjust based on your system's capabilities
    private static final int BATCH_SIZE = 1000; // Adjust based on your data volume
    private static final ObjectMapper mapper = new ObjectMapper();
    private static final ConcurrentHashMap<String, JsonNode> cache = new ConcurrentHashMap<>();

    public static void main(String[] args) {
        // Assuming metadataFiles is a list of File objects containing JSON data
        List<File> metadataFiles = new ArrayList<>();
        // Populate metadataFiles list with your data

        // Split metadata files into batches
        List<List<File>> batches = splitIntoBatches(metadataFiles, BATCH_SIZE);

        // Create a thread pool
        ExecutorService executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);

        // Process each batch in parallel
        for (List<File> batch : batches) {
            executorService.submit(() -> {
                for (File file : batch) {
                    try {
                        parseJsonFile(file);
                    } catch (IOException e) {
                        logger.error("Error parsing JSON file: {}", file, e);
                    }
                }
            });
        }

        // Shutdown the executor service
        executorService.shutdown();
        try {
            executorService.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            logger.error("Thread interrupted", e);
        }

        logger.info("JSON parsing completed.");
    }

    private static List<List<File>> splitIntoBatches(List<File> files, int batchSize) {
        return files.stream()
                .collect(Collectors.groupingBy(it -> files.indexOf(it) / batchSize))
                .values()
                .stream()
                .map(list -> list.stream().map(File.class::cast).collect(Collectors.toList()))
                .collect(Collectors.toList());
    }

    private static void parseJsonFile(File file) throws IOException {
        String filePath = file.getAbsolutePath();
        if (cache.containsKey(filePath)) {
            logger.debug("Using cached JSON for file: {}", filePath);
            return;
        }

        JsonNode jsonNode = mapper.readTree(file);
        cache.put(filePath, jsonNode);
        logger.debug("Parsed JSON for file: {}", filePath);
    }
}
