```java
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.dataformat.zip.ZipFactory;
import com.fasterxml.jackson.core.type.TypeReference;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.ConcurrentHashMap;

public class JsonParserOptimizer {

    private static final ObjectMapper mapper = new ObjectMapper();
    private static final ZipFactory zipFactory = new ZipFactory();
    private static final ConcurrentHashMap<String, JsonNode> cache = new ConcurrentHashMap<>();
    private static final int THREAD_POOL_SIZE = 4; // Adjust based on your system's capabilities
    private static final int BATCH_SIZE = 1000; // Adjust based on your data volume

    public static void main(String[] args) {
        // Directory containing the compressed JSON files
        File directory = new File("/path/to/json/files");

        // List all files in the directory
        File[] files = directory.listFiles((dir, name) -> name.endsWith(".json.zip"));

        // Split files into batches
        List<List<File>> batches = splitIntoBatches(files, BATCH_SIZE);

        // Create a thread pool
        ExecutorService executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);

        // Measure start time
        long startTime = System.currentTimeMillis();

        // Process each batch in parallel
        for (List<File> batch : batches) {
            executorService.submit(() -> {
                for (File file : batch) {
                    try {
                        parseJsonFile(file);
                    } catch (IOException e) {
                        System.err.println("Error parsing JSON file: " + file.getName());
                        e.printStackTrace();
                    }
                }
            });
        }

        // Shutdown the executor service
        executorService.shutdown();
        try {
            executorService.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Thread interrupted");
            e.printStackTrace();
        }

        // Measure end time
        long endTime = System.currentTimeMillis();
        long duration = endTime - startTime;
        System.out.println("JSON parsing completed in " + duration + " ms.");

        // Calculate throughput
        double throughput = files.length / (duration / 1000.0);
        System.out.println("Throughput: " + throughput + " files per second.");
    }

    private static List<List<File>> splitIntoBatches(File[] files, int batchSize) {
        List<List<File>> batches = new ArrayList<>();
        for (int i = 0; i < files.length; i += batchSize) {
            int end = Math.min(i + batchSize, files.length);
            batches.add(new ArrayList<>(List.of(Arrays.copyOfRange(files, i, end))));
        }
        return batches;
    }

    private static void parseJsonFile(File file) throws IOException {
        String filePath = file.getAbsolutePath();
        if (cache.containsKey(filePath)) {
            System.out.println("Using cached JSON for file: " + filePath);
            return;
        }

        // Use ZipFactory to handle compressed JSON files
        mapper.configure(zipFactory.createParser(file));
        JsonNode jsonNode = mapper.readTree(file);
        cache.put(filePath, jsonNode);
        System.out.println("Parsed JSON for file: " + filePath);
    }
}
```

### Explanation

1. **Data Compression**:
   - Use `ZipFactory` to handle compressed JSON files. This reduces the amount of data that needs to be read from disk or network.

2. **Caching**:
   - Use a `ConcurrentHashMap` to cache parsed JSON nodes. This avoids redundant parsing operations for the same file.

3. **Parallel Processing**:
   - Use an `ExecutorService` to process batches of files in parallel. This distributes the parsing load across multiple threads.

4. **Batch Processing**:
   - Split the list of files into smaller batches to manage memory usage and improve performance.

5. **Monitoring and Logging**:
   - Measure the start and end times to calculate the total parsing duration and throughput.
   - Log any errors encountered during parsing.

### Additional Considerations

- **Compression Level**: Adjust the compression level based on the trade-off between compression ratio and decompression speed.
- **Memory Management**: Monitor memory usage to ensure that the caching mechanism does not consume too much memory.
- **Error Handling**: Implement robust error handling to manage exceptions and ensure data integrity.

### Conclusion

By incorporating data compression, caching, parallel processing, and batch processing, you can significantly optimize JSON parsing performance using Jackson 2.14.0. This approach ensures that the parsing speed remains consistent even with increasing data sizes, making your system more efficient and scalable.

