#### 2. Load the Custom Configuration in Your Java Code

```java
import org.apache.tika.Tika;
import org.apache.tika.config.TikaConfig;
import org.apache.tika.parser.AutoDetectParser;
import org.apache.tika.parser.ParseContext;
import org.apache.tika.sax.BodyContentHandler;
import org.apache.tika.metadata.Metadata;
import org.apache.tika.exception.TikaException;
import org.xml.sax.ContentHandler;
import org.xml.sax.SAXException;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;

public class MetadataExtractor {

    public static void main(String[] args) {
        Path directoryPath = Paths.get("path/to/directory");
        List<Path> files = getFiles(directoryPath);

        try {
            TikaConfig config = TikaConfig.getDefaultConfig();
            Tika tika = new Tika(config);

            for (Path filePath : files) {
                try {
                    extractMetadata(tika, filePath);
                } catch (IOException | SAXException | TikaException e) {
                    System.err.println("Error processing file " + filePath + ": " + e.getMessage());
                }
            }
        } catch (IOException e) {
            System.err.println("Error loading Tika configuration: " + e.getMessage());
        }
    }

    private static List<Path> getFiles(Path directoryPath) {
        try {
            return Files.walk(directoryPath)
                        .filter(path -> !path.toFile().isDirectory())
                        .collect(Collectors.toList());
        } catch (IOException e) {
            throw new RuntimeException("Error walking directory: " + directoryPath, e);
        }
    }

    private static void extractMetadata(Tika tika, Path filePath) throws IOException, SAXException, TikaException {
        ContentHandler handler = new BodyContentHandler(-1);
        Metadata metadata = new Metadata();
        FileInputStream inputstream = new FileInputStream(filePath.toFile());

        tika.parse(inputstream, handler, metadata, new ParseContext());

        System.out.println("File: " + filePath);
        System.out.println("Title: " + metadata.get("title"));
        System.out.println("Author: " + metadata.get("Author"));
        System.out.println("Creation Date: " + metadata.get("Creation-Date"));
        System.out.println("Content: " + handler.toString());
    }
}
```

### Explanation

