    public ElasticsearchExample(RestHighLevelClient client) {
        this.client = client;
    }

    public void performIndexOperation(String indexName, String documentId, String documentContent) {
        try {
            // Check if the index exists
            boolean indexExists = client.indices().exists(new GetIndexRequest(indexName), RequestOptions.DEFAULT);
            if (!indexExists) {
                System.out.println("Index does not exist: " + indexName);
                // Optionally, create the index here if it doesn't exist
                // client.indices().create(createIndexRequest, RequestOptions.DEFAULT);
                return;
            }

            // Indexing code here
