app = Flask(__name__)

# Define user roles and their rate limits
USER_ROLES = {
    'admin': '100/minute',
    'premium': '50/minute',
    'basic': '20/minute'
}

# Custom key function to identify user roles
def get_user_role():
    # Assume user role is stored in the request context
    return getattr(g, 'user_role', 'basic')

# Configure Flask-Limiter with custom key function
limiter = Limiter(
    app,
    key_func=get_user_role,
    default_limits=["20/minute"]
)

# Decorator to set user role for the request
def set_user_role(role):
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            g.user_role = role
            return f(*args, **kwargs)
        return decorated_function
    return decorator

# Custom rate limit for the specific endpoint
@app.route("/api/v1/admin-endpoint", methods=["GET"])
@set_user_role('admin')
@limiter.limit(USER_ROLES['admin'])
def admin_handle_request():
    # Handle the request
    return jsonify({"message": "Admin request handled successfully"})

@app.route("/api/v1/premium-endpoint", methods=["GET"])
@set_user_role('premium')
@limiter.limit(USER_ROLES['premium'])
def premium_handle_request():
    # Handle the request
    return jsonify({"message": "Premium request handled successfully"})

@app.route("/api/v1/basic-endpoint", methods=["GET"])
@set_user_role('basic')
@limiter.limit(USER_ROLES['basic'])
def basic_handle_request():
    # Handle the request
    return jsonify({"message": "Basic request handled successfully"})

# Custom error handler for 429 status code
@app.errorhandler(429)
def ratelimit_handler(e):
    return jsonify(error="ratelimit", description=str(e.description)), 200

if __name__ == "__main__":
    app.run(debug=True)
```

### Conclusion

By using a custom key function and conditional rate limits, you can implement different rate limits for different user roles without switching to Redis. This approach allows you to handle bursts more gracefully and provide more tailored rate limits based on user roles.

