Integrating OAuth2 with an existing user authentication system involves several steps. You need to ensure that your OAuth2 provider can validate tokens and that your application can securely handle user authentication and authorization. Here's a step-by-step guide to help you integrate OAuth2 with your existing user authentication system:

### Step 1: Define User Authentication Model

First, define a model for your users and their roles. This model will be used to validate user credentials and assign roles.

```python
from pydantic import BaseModel
from typing import List

class User(BaseModel):
    username: str
    password: str
    role: str
```

### Step 2: Implement User Authentication

Implement a function to authenticate users and generate JWT tokens. This function will validate user credentials and issue a token if the credentials are correct.

```python
from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm
from jose import jwt, JWTError
from pydantic import BaseModel
from typing import List
from datetime import datetime, timedelta

app = FastAPI()

# OAuth2 scheme
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")

# Secret key for JWT validation
SECRET_KEY = "your_secret_key"
ALGORITHM = "HS256"
ACCESS_TOKEN_EXPIRE_MINUTES = 30

# Sample user database
users_db = {
    "user1": {"username": "user1", "password": "password1", "role": "user"},
    "admin1": {"username": "admin1", "password": "password2", "role": "admin"}
}

# Function to authenticate user and generate token
def authenticate_user(username: str, password: str):
    user = users_db.get(username)
    if user and user["password"] == password:
        return user
    return None

def create_access_token(data: dict, expires_delta: timedelta = None):
    to_encode = data.copy()
    if expires_delta:
        expire = datetime.utcnow() + expires_delta
    else:
        expire = datetime.utcnow() + timedelta(minutes=15)
    to_encode.update({"exp": expire})
    encoded_jwt = jwt.encode(to_encode, SECRET_KEY, algorithm=ALGORITHM)
    return encoded_jwt

@app.post("/token", response_model=dict)
def login_for_access_token(form_data: OAuth2PasswordRequestForm = Depends()):
    user = authenticate_user(form_data.username, form_data.password)
    if not user:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Incorrect username or password",
            headers={"WWW-Authenticate": "Bearer"},
        )
    access_token_expires = timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
    access_token = create_access_token(
        data={"sub": user["username"], "role": user["role"]}, expires_delta=access_token_expires
    )
    return {"access_token": access_token, "token_type": "bearer"}
```

### Step 3: Define Token Payload Model

Define a Pydantic model to represent the token payload.

```python
class TokenPayload(BaseModel):
    sub: str
    role: str
```

### Step 4: Implement Token Validation

Implement the `get_current_user_role` function to validate the token and extract the user role.

```python
def get_current_user_role(token: str = Depends(oauth2_scheme)):
    credentials_exception = HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail="Could not validate credentials",
        headers={"WWW-Authenticate": "Bearer"},
    )
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        token_data = TokenPayload(**payload)
    except JWTError:
        raise credentials_exception
    return token_data.role
```

### Step 5: Define Sensitive Endpoints

Identify sensitive endpoints and restrict access based on the user role.

```python
# Define sensitive endpoints
SENSITIVE_ENDPOINTS = ["/api/v1/financials", "/api/v1/personal-data"]

# Define roles
ROLES = {
    "admin": ["admin"],
    "manager": ["manager"],
    "user": ["user"],
    "guest": ["guest"]
}
```

### Step 6: Implement Middleware for RBAC

Implement middleware to enforce role-based access control.

```python
class RBACMiddleware:
    def __init__(self, app):
        self.app = app

    async def __call__(self, scope, receive, send):
        if scope["type"] == "http":
            path = scope["root_path"] + scope["path"]
            if path in SENSITIVE_ENDPOINTS:
                role = get_current_user_role(scope)
                if role not in ROLES["admin"]:
                    raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Not enough permissions")
        await self.app(scope, receive, send)

app.add_middleware(RBACMiddleware)
```

### Step 7: Define Example Endpoints

Define example endpoints with role-based access control enforced.

```python
@app.get("/api/v1/public")
def public_endpoint():
    return {"message": "Public endpoint"}

@app.get("/api/v1/financials")
def financials_endpoint(current_user_role: str = Depends(get_current_user_role)):
    if current_user_role not in ROLES["admin"]:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Not enough permissions")
    return {"message": "Financials endpoint"}

@app.get("/api/v1/personal-data")
def personal_data_endpoint(current_user_role: str = Depends(get_current_user_role)):
    if current_user_role not in ROLES["admin"]:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Not enough permissions")
    return {"message": "Personal data endpoint"}

@app.get("/api/v1/user-data")
def user_data_endpoint(current_user_role: str = Depends(get_current_user_role)):
    if current_user_role not in ROLES["user"]:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Not enough permissions")
    return {"message": "User data endpoint"}
```

