```java
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import java.util.ArrayList;
import java.util.List;

public class AuthProfiler {

    private static final int TARGET_LATENCY_MS = 90;
    private static final int NUM_LOGINS = 4000;
    private static final double PERCENTILE = 0.90;
    private static List<Long> latencies = new ArrayList<>();

    public static void main(String[] args) {
        // Initialize authentication manager
        AuthenticationManager authenticationManager = new AuthenticationManager();

        // Simulate 4K daily logins
        for (int i = 0; i < NUM_LOGINS; i++) {
            long startTime = System.currentTimeMillis();

            // Define authentication request
            UsernamePasswordAuthenticationToken authenticationRequest = new UsernamePasswordAuthenticationToken("username", "password");

            // Authenticate user
            Authentication authentication = authenticationManager.authenticate(authenticationRequest);

            // Validate token
            if (authentication.isAuthenticated()) {
                System.out.println("Token validated successfully");
            } else {
                System.out.println("Token validation failed");
            }

            long endTime = System.currentTimeMillis();
            long latency = endTime - startTime;
            latencies.add(latency);
        }

        // Calculate the 90th percentile of latencies
        double percentile90 = calculatePercentile(latencies, PERCENTILE);
        System.out.printf("90th percentile latency: %.2f ms%n", percentile90);

        // Check if the 90th percentile meets the target latency
        if (percentile90 <= TARGET_LATENCY_MS) {
            System.out.println("Target latency of " + TARGET_LATENCY_MS + "ms met.");
        } else {
            System.out.printf("Target latency of %dms not met. Current 90th percentile latency is %.2fms.%n", TARGET_LATENCY_MS, percentile90);
        }
    }

    private static double calculatePercentile(List<Long> latencies, double percentile) {
        int size = latencies.size();
        int index = (int) Math.ceil(percentile * size) - 1;
        latencies.sort(Long::compare);
        return latencies.get(index);
    }
}
```

### Explanation

