from functools import wraps
from flask import g, abort

def requires_roles(*roles):
    def wrapper(fn):
        @wraps(fn)
        def decorated_view(*args, **kwargs):
            if g.user_role not in roles:
                abort(403)
            return fn(*args, **kwargs)
        return decorated_view
    return wrapper
