Certainly! To achieve high availability and support 3,000 concurrent queries with 99.95% uptime, you should consider using an Application Load Balancer (ALB) instead of the classic Elastic Load Balancer (ELB). ALBs offer more advanced features and better performance, especially for HTTP/HTTPS traffic.

Here's an improved Terraform configuration that sets up an Application Load Balancer with high availability and proper health checks:

### Terraform Configuration

1. **Define Subnets and Security Groups**

   Ensure you have subnets and security groups defined for your VPC. These will be used by the load balancer.

   ```hcl
   resource "aws_vpc" "example" {
     cidr_block = "10.0.0.0/16"
   }

   resource "aws_subnet" "subnet1" {
     vpc_id     = aws_vpc.example.id
     cidr_block = "10.0.1.0/24"
     availability_zone = "us-west-2a"
   }

   resource "aws_subnet" "subnet2" {
     vpc_id     = aws_vpc.example.id
     cidr_block = "10.0.2.0/24"
     availability_zone = "us-west-2b"
   }

   resource "aws_security_group" "load_balancer_sg" {
     name        = "load_balancer_sg"
     description = "Security group for load balancer"
     vpc_id      = aws_vpc.example.id

     ingress {
       from_port   = 80
       to_port     = 80
       protocol    = "tcp"
       cidr_blocks = ["0.0.0.0/0"]
     }

     egress {
       from_port   = 0
       to_port     = 0
       protocol    = "-1"
       cidr_blocks = ["0.0.0.0/0"]
     }
   }
   ```

2. **Define the Application Load Balancer**

   Configure the ALB with the appropriate subnets and security groups. Also, define a target group and health checks.

   ```hcl
   resource "aws_lb" "application_load_balancer" {
     name               = "document-pipeline-alb"
     internal           = false
     load_balancer_type = "application"
     security_groups    = [aws_security_group.load_balancer_sg.id]
     subnets            = [aws_subnet.subnet1.id, aws_subnet.subnet2.id]

     enable_deletion_protection = false

     tags = {
       Name = "document-pipeline-alb"
     }
   }

   resource "aws_lb_target_group" "target_group" {
     name     = "document-pipeline-target-group"
     port     = 80
     protocol = "HTTP"
     vpc_id   = aws_vpc.example.id

     health_check {
       path                = "/"
       interval            = 30
       timeout             = 5
       healthy_threshold   = 5
       unhealthy_threshold = 2
     }
   }

   resource "aws_lb_listener" "listener" {
     load_balancer_arn = aws_lb.application_load_balancer.arn
     port              = "80"
     protocol          = "HTTP"

     default_action {
       type             = "forward"
       target_group_arn = aws_lb_target_group.target_group.arn
     }
   }
   ```

3. **Register Targets**

   Register your instances or containers to the target group. This can be done using `aws_lb_target_group_attachment` resources.

   ```hcl
   resource "aws_instance" "web_server1" {
     ami           = "ami-abc123"
     instance_type = "t2.micro"
     subnet_id     = aws_subnet.subnet1.id
     security_groups = [aws_security_group.load_balancer_sg.id]

     tags = {
       Name = "web-server1"
     }
   }

   resource "aws_instance" "web_server2" {
     ami           = "ami-abc123"
     instance_type = "t2.micro"
     subnet_id     = aws_subnet.subnet2.id
     security_groups = [aws_security_group.load_balancer_sg.id]

     tags = {
       Name = "web-server2"
     }
   }

   resource "aws_lb_target_group_attachment" "attachment1" {
     target_group_arn = aws_lb_target_group.target_group.arn
     target_id        = aws_instance.web_server1.id
     port             = 80
   }

   resource "aws_lb_target_group_attachment" "attachment2" {
     target_group_arn = aws_lb_target_group.target_group.arn
     target_id        = aws_instance.web_server2.id
     port             =  80
   }
   ```

### Explanation

1. **Subnets and Security Groups**: Define subnets and security groups to ensure the load balancer and instances are properly isolated and secured.
2. **Application Load Balancer**: Use an ALB with the appropriate subnets and security groups. Define a target group with health checks to ensure only healthy instances receive traffic.
3. **Listeners**: Configure listeners to route incoming traffic to the target group.
4. **Targets**: Register your instances to the target group so they can receive traffic from the load balancer.

### Conclusion

By following this configuration, you can set up a highly available Application Load Balancer that supports 3,000 concurrent queries with 99.95% uptime. The health checks and multiple subnets ensure that the load balancer can handle failures gracefully.

